/// <summary>
/// Ensures that the UnityEngine.Mesh associated with this object is unique. When instantiating a ProBuilderMesh,
/// the mesh asset will reference the original instance. If you are making a copy to edit, you must call
/// MakeUnique to avoid modifying a shared mesh asset.
/// </summary>
public void MakeUnique()
{
    mesh = mesh != null
        ? Instantiate(mesh)
        : new Mesh();
    mesh.name = $"pb_Mesh{this.GetObjectId()}";

    if (meshSyncState == MeshSyncState.InSync)
    {
        filter.mesh = mesh;
        return;
    }

    ToMesh();
    Refresh();
}

/// <summary>
/// Copies the mesh data from another mesh to this one.
/// </summary>
/// <param name="other">The mesh to copy from.</param>
public void CopyFrom(ProBuilderMesh other)
{
    if (other == null)
        throw new ArgumentNullException(nameof(other));

    Clear();
    positions = other.positions;
    sharedVertices = other.sharedVerticesInternal;
    SetSharedTextures(other.sharedTextureLookup);
    facesInternal = other.faces.Select(x => new Face(x)).ToArray();

    List<Vector4> uvs = new List<Vector4>();

    for (var i = 0; i < k_UVChannelCount; i++)
    {
        other.GetUVs(i, uvs);
        SetUVs(i, uvs);
    }

    tangents = other.tangents;
    colors = other.colors;
    userCollisions = other.userCollisions;
    selectable = other.selectable;
    unwrapParameters = new UnwrapParameters(other.unwrapParameters);
}

/// <summary>
/// Gets a flag that indicates whether the <see cref="UnityEngine.Mesh" /> is in sync with the ProBuilderMesh.
/// </summary>
/// <value>
/// A flag that describes the state of the synchronicity between the
/// <see cref="UnityEngine.MeshFilter.sharedMesh" /> and ProBuilderMesh components.
/// </value>
public MeshSyncState meshSyncState
{
    get
    {
        if (mesh == null)
            return MeshSyncState.Null;

        // if the local version index is uninitialized, that means no edits have occurred since loading this
        // mesh. it could mean a new mesh was created and ToMesh has not been called yet, or that this mesh was
        // copy/pasted from an existing instance.
        // in the latter case, it is handled by listening to the ObjectChangeEvent stream in HierarchyListener.
        // this function only cares about the case where modifications have been made during the current session.
        if (m_VersionIndex != m_InstanceVersionIndex && m_InstanceVersionIndex != k_UnitializedVersionIndex)
            return MeshSyncState.NeedsRebuild;

        return mesh.uv2 == null ? MeshSyncState.Lightmap : MeshSyncState.InSync;
    }
